



const tabGroup=Ti.UI.createTabGroup();




tabGroup.addTab(createTab("Tab 1","I am Window 1","assets/images/tab1.png")),
tabGroup.addTab(createTab("Tab 2","I am Window 2","assets/images/tab2.png")),




tabGroup.open();








function createTab(title,message,icon){const
window=Ti.UI.createWindow({
backgroundColor:"backgroundColor",
title:title
}),

label=Ti.UI.createLabel({
text:message,
color:"textColor"
});



return window.add(label),Ti.UI.createTab({
title:title,
icon:icon,
window:window
})
}
